import {aggregate,filterDays,recommend,csv,unique} from './core.mjs';
import {thumbnailAssets} from './thumbnail-data.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], nf=new Intl.NumberFormat('ko-KR'), fmt=x=>nf.format(x), anchor='2026-10-23';
const channels=[{id:'instagram',name:'Instagram',icon:'◎',color:'#c792a8',base:4280},{id:'facebook',name:'Facebook',icon:'f',color:'#89a6cf',base:2350},{id:'youtube',name:'YouTube',icon:'▶',color:'#d99a87',base:1820},{id:'x',name:'X',icon:'𝕏',color:'#87968b',base:1260}];
const dayAdd=(s,n)=>{let d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)},monday=s=>{let d=new Date(s+'T00:00:00Z');return dayAdd(s,-(d.getUTCDay()+6)%7)},today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date()), weekStart=monday(today),weekEnd=dayAdd(weekStart,6),dateLabel=s=>s.replaceAll('-','.');
const titles=['부산, 골목 사이의 작은 발견','하루를 천천히 걷는 방법','바다를 담은 15초','우리 동네 숨은 장소 3곳','노을이 머무는 시간','이번 주말 여기 어때요?','한 장으로 남긴 부산의 색','저장하고 싶은 여행 코스','로컬이 추천하는 작은 카페','가을 바람 따라 떠난 산책','다시 보고 싶은 오늘의 순간','취향을 발견하는 여행'];
function thumbnail(p){const asset=thumbnailAssets[titles.indexOf(p.title)]||thumbnailAssets[0];const video=p.format==='Shorts'||p.format==='Reels'||p.format==='동영상';return `<div class="content-thumbnail"><img src="${asset}" alt="${p.title} · 샘플 썸네일" width="96" height="64" loading="lazy" decoding="async">${video?'<span class="thumbnail-play" aria-hidden="true">▶</span>':''}<span class="thumbnail-format">${p.format}</span></div>`;}
let posts=[],raw=[];
for(let c=0;c<4;c++)for(let i=0;i<14;i++){const published=dayAdd('2026-09-12',i*3+(c%2));if(published>anchor)continue;const p={postId:`${channels[c].id}-${i+1}`,channel:channels[c].id,title:titles[(i+c*2)%12],published,format:c===2?'Shorts':c===0?(i%2?'캐러셀':'Reels'):c===1?'동영상':'포스트'};posts.push(p);for(let date=published;date<=anchor;date=dayAdd(date,1)){let age=(new Date(date)-new Date(published))/864e5;const views=Math.round((c===0?500:c===1?230:c===2?390:140)/(1+age*.45)*(0.8+((i*7+age*3+c)%9)/15));raw.push({date,channel:p.channel,postId:p.postId,title:p.title,published,format:p.format,views,saves:c===3?0:Math.round(views*(c===0?.025:.008)),reposts:c===3?Math.round(views*.02):0,shares:Math.round(views*.012),comments:Math.round(views*.007),followers:channels[c].base+Math.floor((new Date(date)-new Date('2026-09-12'))/864e5)*(c===0?7:c===1?3:c===2?5:2)});}}
// A reproducible, explicitly synthetic week at 84.6% of the initial 10,000-view goal.
const sampleWeek=monday(anchor),sampleRows=raw.filter(r=>r.date>=sampleWeek),original=sampleRows.reduce((s,r)=>s+r.views,0);let assigned=0;sampleRows.forEach((r,i)=>{r.views=i===sampleRows.length-1?8460-assigned:Math.round(r.views*8460/original);assigned+=r.views;r.saves=r.channel==='x'?0:Math.round(r.views*(r.channel==='instagram'?.025:.008));r.shares=Math.round(r.views*.012);r.reposts=r.channel==='x'?Math.round(r.views*.02):0;r.comments=Math.round(r.views*.007)});
