function renderChart(rows){let dates=[...new Set(rows.map(r=>r.date))].sort(),vals=dates.map(d=>aggregate(rows.filter(r=>r.date===d)).views),max=Math.ceil(Math.max(...vals,1)/500)*500;const W=660,H=165,left=42,right=12,top=12,bottom=26;let plotH=H-top-bottom,plotW=W-left-right;let pts=vals.map((v,i)=>`${left+i/(vals.length-1||1)*plotW},${top+(1-v/max)*plotH}`);let grid=[0,.5,1].map(t=>`<line x1="${left}" x2="${W-right}" y1="${top+t*plotH}" y2="${top+t*plotH}" stroke="#edf0e9" stroke-dasharray="3 4"/><text x="${left-10}" y="${top+t*plotH+3}" text-anchor="end" fill="#a5afa0" font-size="9">${fmt(max*(1-t))}</text>`).join('');let labels=dates.map((d,i)=>i===0||i===dates.length-1||i===Math.floor(dates.length/2)?`<text x="${left+i/(dates.length-1||1)*plotW}" y="${H-4}" text-anchor="middle" fill="#9eaa98" font-size="9">${d.slice(5).replace('-','.')}</text>`:'').join('');$('#trendChart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${dates.length}일의 일별 조회수 추이"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9ebc8b" stop-opacity=".22"/><stop offset="1" stop-color="#9ebc8b" stop-opacity="0"/></linearGradient></defs>${grid}${pts.length?`<path d="M${left},${top+plotH} L${pts.join(' L')} L${left+plotW},${top+plotH} Z" fill="url(#fade)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#82a371" stroke-width="2"/>`:''}${labels}</svg>`;}
function contentStats(){const rows=selected();return posts.filter(p=>(channel==='all'||p.channel===channel)&&rows.some(r=>r.postId===p.postId)).map(p=>({...p,...aggregate(rows.filter(r=>r.postId===p.postId))})).sort((a,b)=>b[sort]-a[sort]);}
function renderContent(){const all=contentStats();$('#contentBody').innerHTML=all.map((p,i)=>{let c=channels.find(c=>c.id===p.channel);return `<tr><td><div class="content-title">${thumbnail(p)}<div><strong>${p.title}</strong><small>${p.format} · ${p.postId}</small></div></div></td><td><span class="channel-pill ${p.channel}">${c.name}</span></td><td>${dateLabel(p.published)}</td><td>${fmt(p.views)}</td><td>${fmt(p.conversions)}</td><td>${fmt(p.comments)}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">선택한 기간에 성과 데이터가 없습니다.</td></tr>';$('.content-table th:nth-child(4)').textContent=sort==='views'?'조회수 ↓':'조회수';$('.content-table th:nth-child(5)').textContent=sort==='conversions'?'전환 수 ↓':'전환 수';$('.content-table th:nth-child(6)').textContent=sort==='comments'?'댓글 수 ↓':'댓글 수';$('#contentCount').textContent=`총 ${all.length}개 콘텐츠 · 썸네일은 구분용 샘플 이미지입니다 · 성과는 선택 기간 내 발생분, 게시일은 최초 업로드일 · 채널 + 게시물 ID 기준 중복 제거`}
