function history(){const list=[...stored.history].reverse();$('#historyList').replaceChildren();for(const item of list){let div=document.createElement('article');div.className='history-item';let t=document.createElement('time'),h=document.createElement('h3'),p=document.createElement('p');t.textContent=item.at;h.textContent='주간 KPI 목표 변경';p.textContent=item.text;div.append(t,h,p);$('#historyList').append(div)}const thumbnailRelease=document.createElement('article');thumbnailRelease.className='history-item';thumbnailRelease.innerHTML='<time>2026.10.23 · v1.1.0</time><h3>콘텐츠 썸네일 이미지 추가</h3><p>콘텐츠 주제에 맞는 12종의 샘플 사진을 추가했습니다. 제목별 썸네일은 필터와 정렬에 관계없이 유지되며, 영상 콘텐츠에는 재생 아이콘과 형식을 표시합니다.<br>단일 HTML 파일에 이미지를 포함해 오프라인에서도 확인하실 수 있습니다.</p>';$('#historyList').append(thumbnailRelease);const release=document.createElement('article');release.className='history-item';release.innerHTML='<time>2026.10.23 · v1.0.0</time><h3>SNS 성과를 한 곳에서, Social Pulse 오픈</h3><p>4개 채널 주간 목표·달성률, 1일·7일·30일·전체 기간 필터, 채널·콘텐츠별 인사이트를 추가했습니다.<br>고유 게시물 집계, 저장·공유·리포스트 합산, CSV 다운로드, 목표 추천과 브라우저 저장을 지원합니다.<br>실제 SNS API는 연결되어 있지 않습니다. 월요일 오전 9시 알림은 Codex에서 별도로 실행됩니다.</p>';$('#historyList').append(release)}
function route(){const name=location.hash.slice(1)||'dashboard',hist=name==='history',content=name==='content';$('#dashboardView').hidden=hist||content;$('#contentPanel').hidden=hist;$('#historyView').hidden=!hist;$('#pageTitle').textContent=hist?'성장의 기록을 남깁니다.':content?'좋은 콘텐츠에는 신호가 있습니다.':'채널의 성장을 한눈에.';$('#pageSubtitle').textContent=hist?'새로운 기능과 우리 팀의 목표 변경 이력을 확인하세요.':content?'기간과 채널을 선택해 콘텐츠 성과를 비교하세요.':'흩어져 있던 성과를 모아, 다음 성장을 계획하세요.';$('#breadcrumb').textContent=hist?'업데이트 기록':content?'콘텐츠 분석':'대시보드';$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===name));if(hist)history();if(content&&!$('#contentPeriod')){let clone=$('.filters').cloneNode(true);clone.id='contentPeriod';clone.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>setDays(+b.dataset.days)));$('.content-controls').before(clone);clone.style.cssText='margin:0 24px 15px;width:max-content'}syncFilters();}
function syncFilters(){$$('[data-days]').forEach(b=>b.classList.toggle('active',+b.dataset.days===days))}function setDays(n){days=n;syncFilters();render()}
$$('[data-days]').forEach(b=>b.onclick=()=>setDays(+b.dataset.days));$$('[data-channel]').forEach(b=>b.onclick=()=>{channel=b.dataset.channel;$$('[data-channel]').forEach(x=>x.classList.toggle('active',x===b));renderContent()});$('#sortMetric').onchange=e=>{sort=e.target.value;renderContent()};$('#exportAll').onclick=()=>download('daily-data',data.map(r=>({...r,weekly_goal:goal(),goal_week_start:weekStart,data_type:'demo'})));$('#exportChannels').onclick=()=>download('channels',window.channelStats.map(r=>({period_start:startDate(),period_end:anchor,...r,data_type:'demo'})));$('#exportContent').onclick=()=>download('content',contentStats().map(({followers,...r})=>({period_start:startDate(),period_end:anchor,...r,data_type:'demo'})));
function openGoal(){const r=recommendation();$('#dialogWeek').textContent=`${dateLabel(weekStart)} — ${dateLabel(weekEnd)} · 한국시간`;$('#goalInput').value=goal();$('#recommendedValue').textContent=r.value?`추천 목표 ${fmt(r.value)}회`:'추천 데이터가 부족합니다';$('#recommendBasis').textContent=r.value?`완료된 ${r.weeks.length}주 평균 ${fmt(Math.round(r.weeks.reduce((s,w)=>s+w.views,0)/r.weeks.length))}회 × 1.10, 100회 단위 올림. 임의 데이터 기준입니다.`:'완료된 주간 실적 데이터가 필요합니다.';$('#useRecommendation').disabled=!r.value;$('#goalDialog').showModal()}
$('#editGoal').onclick=openGoal;$('#recommendButton').onclick=openGoal;$('#closeDialog').onclick=()=>$('#goalDialog').close();$('#useRecommendation').onclick=()=>{$('#goalInput').value=recommendation().value};$('#goalForm').onsubmit=e=>{e.preventDefault();const v=Number($('#goalInput').value);if(!Number.isSafeInteger(v)||v<=0||v>1e9)return;const previous=goal();stored.goals[weekStart]=v;stored.history.push({at:new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'}).format(new Date()),text:`${dateLabel(weekStart)} 주간 목표: ${fmt(previous)}회 → ${fmt(v)}회`});const ok=save();renderGoal();history();$('#goalDialog').close();toast(ok?'이번 주 목표를 저장했습니다.':'현재 화면에만 반영되었습니다. 브라우저 저장은 제한되어 있습니다.');};window.addEventListener('hashchange',route);render();route();if(!storageOK)toast('브라우저 저장이 제한되어 목표가 영구 저장되지 않을 수 있습니다.');
